fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    assert!(!v.is_empty());

    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1;

    while lo < hi {
        // mid is always in [lo, hi), so mid + 1 is <= hi when needed
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // Under the stated assumption that k occurs in v, this must hold.
    debug_assert!(v[lo] == k);
    lo
}